'use strict';
(function(){
const layers=new Map();
function add(layer){if(!layer.id||layers.has(layer.id))throw Error('Duplicate or absent geography layer ID');if(!layer.role||!layer.crs||!layer.source||!layer.license)throw Error('Geography provenance required');if(layer.geometry){if(layer.crs!=='EPSG:4326')throw Error('Geographic layers require declared WGS84');const check=p=>{if(!Array.isArray(p)||p.length<2||!p.every(Number.isFinite)||Math.abs(p[0])>180||Math.abs(p[1])>90)throw Error('Invalid geographic position');};if(layer.geometry.type==='Point'){if(layer.role!=='city-centre')throw Error('Point role must be explicit');check(layer.geometry.coordinates);}else if(['Polygon','MultiPolygon'].includes(layer.geometry.type)){for(const ring of (layer.geometry.type==='MultiPolygon'?layer.geometry.coordinates.flat():layer.geometry.coordinates)){if(ring.length<4||JSON.stringify(ring[0])!==JSON.stringify(ring.at(-1)))throw Error('Unclosed geography ring');ring.forEach(check);}}else throw Error('Unsupported layer geometry');}layers.set(layer.id,Object.freeze(layer));return layer;}
const m=window.PoeticsStateMap,a=window.PoeticsAtlas,d=window.PoeticsOSMStateLocators;
if(m)add({id:'nigeria-state-svg',role:'state-boundaries',crs:'native-svg-744x600',source:m.metadata.sourceURL,license:m.metadata.license,reviewStatus:'Existing SVG paths; not geographic coordinates',data:m.states});
for(const [city,p]of Object.entries(a?.placeCoordinates||{}))add({id:'geonames-centre-'+city,role:'city-centre',state:m?.cityStates[city]||null,city,crs:'EPSG:4326',geometry:{type:'Point',coordinates:[p.lon,p.lat]},source:p.source,license:'GeoNames CC BY; retain source attribution',reviewStatus:'City-centre locator; no venue precision',sourceVintage:null});
if(d){add({id:'osm-kaduna-state',role:'state-boundary',state:d.state,crs:'EPSG:4326',geometry:d.geometry,source:'https://www.openstreetmap.org/'+d.stateObject,sourceObject:d.stateObject,license:d.license,extractedAt:d.exportTimestamp,sourceVintage:d.stateSourceDate,reviewStatus:'Uploaded state boundary; no current legal-boundary audit'});for(const c of d.cities)add({id:'osm-centre-'+c.name,role:'city-centre',state:d.state,city:c.name,crs:'EPSG:4326',geometry:{type:'Point',coordinates:c.coordinates},source:'https://www.openstreetmap.org/'+c.object,sourceObject:c.object,license:d.license,extractedAt:d.exportTimestamp,sourceVintage:null,reviewStatus:'Uploaded place=city point; not an urban extent'});}
const u=window.PoeticsUrbanExtents;if(u)for(const f of u.features)add({id:f.id,role:'urban-extent',state:f.state,city:f.city,crs:u.crs,geometry:f.geometry,source:u.source,license:u.license,attribution:u.attribution,sourceVintage:u.vintage,extractedAt:u.extractedAt,reviewStatus:u.scope});
window.PoeticsGeography={add,get:id=>layers.get(id),all:()=>[...layers.values()],forState:state=>[...layers.values()].filter(l=>l.state===state),hasUrbanExtent:state=>[...layers.values()].some(l=>l.state===state&&l.role==='urban-extent')};
})();
